<?php $this->layout('default', ['title' => 'Planos | Realizze', 'description' => 'Conheça os planos do Realizze.']); $money = static fn (mixed $v): string => 'R$ ' . number_format((float) $v, 2, ',', '.'); ?>
<section class="page-hero"><div class="container narrow"><span class="eyebrow">PLANOS</span><h1>Escolha como usar o Realizze.</h1></div></section>
<section class="section"><div class="container"><?php if ($plans === []): ?><p class="rz-empty">Os planos serão divulgados em breve. <a href="/contato">Fale conosco</a> para saber mais.</p><?php else: ?><div class="rz-plans"><?php foreach ($plans as $plan): ?>
<article class="rz-plan<?= $plan['is_featured'] ? ' rz-plan-featured' : '' ?>"><?php if ($plan['is_featured']): ?><span class="rz-plan-tag">Destaque</span><?php endif; ?><h2><?= $this->e($plan['name']) ?></h2><p><?= $this->e($plan['description']) ?></p><p class="rz-plan-price"><strong><?= $this->e($money($plan['monthly_price'])) ?></strong> por mês</p><p class="rz-plan-annual">ou <?= $this->e($money($plan['annual_price'])) ?> por ano</p><ul class="rz-checks"><?php foreach ($plan['benefits'] as $benefit): ?><li><?= $this->e($benefit) ?></li><?php endforeach; ?><?php if ($plan['max_companies'] !== null): ?><li>Até <?= (int) $plan['max_companies'] ?> empresa(s)</li><?php endif; ?><?php if ($plan['max_users'] !== null): ?><li>Até <?= (int) $plan['max_users'] ?> usuário(s)</li><?php endif; ?></ul><a class="btn btn-primary" href="/cadastrar">Começar agora</a></article>
<?php endforeach; ?></div><?php endif; ?></div></section>
